use std::path::PathBuf;

const MANIFEST: &str = "../../packaging/windows/sevenplus.exe.manifest";
const ICON: &str = "../../assets/icons/sevenplus.ico";
const LICENSES: &str = "../../assets/third-party-licenses.txt";

fn main() {
    // Third-party licenses (NFR-042), generated by `cargo about` (see about.toml). The
    // release workflow regenerates the file; SEVENPLUS_LICENSES points to another copy.
    println!("cargo:rerun-if-env-changed=SEVENPLUS_LICENSES");
    println!("cargo:rerun-if-changed={LICENSES}");
    let src = std::env::var("SEVENPLUS_LICENSES").unwrap_or_else(|_| LICENSES.into());
    let text = std::fs::read_to_string(&src).unwrap_or_else(|_| {
        println!("cargo:warning=no third-party license file at {src}; run `cargo about`");
        "Third-party license texts were not generated for this build.\n\
         Run `cargo about generate -o assets/third-party-licenses.txt about.hbs`.\n"
            .into()
    });
    let out = PathBuf::from(std::env::var("OUT_DIR").expect("OUT_DIR is set by cargo"));
    std::fs::write(out.join("third-party-licenses.txt"), text).expect("write licenses");

    // Windows: icon, version info and the application manifest (PKG-002). Resources
    // need the Windows resource compiler, so cross-checks from other hosts skip them.
    println!("cargo:rerun-if-changed={MANIFEST}");
    println!("cargo:rerun-if-changed={ICON}");
    let target_windows = std::env::var("CARGO_CFG_TARGET_OS").as_deref() == Ok("windows");
    let host_windows = std::env::var("HOST").is_ok_and(|h| h.contains("windows"));
    if target_windows && host_windows {
        let version = std::env::var("CARGO_PKG_VERSION").expect("CARGO_PKG_VERSION is set");
        let numeric: Vec<&str> = version.split(['.', '-', '+']).take(3).collect();
        let manifest = std::fs::read_to_string(MANIFEST)
            .expect("read manifest")
            .replace("@VERSION@", &format!("{}.0", numeric.join(".")));
        let mut res = winresource::WindowsResource::new();
        res.set_icon(ICON);
        res.set("FileDescription", "SevenPlus Calculator");
        res.set("ProductName", "SevenPlus Calculator");
        res.set("CompanyName", "Taras Kornuta");
        res.set("LegalCopyright", "Copyright © 2026 Taras Kornuta");
        res.set("OriginalFilename", "sevenplus.exe");
        res.set_manifest(&manifest);
        res.compile().expect("compile Windows resources");
    } else if target_windows {
        println!("cargo:warning=skipping Windows resources (not building on Windows)");
    }
}
